import { I } from './icons.js';
import { store } from './store.js';
import { load, esc, shuffle, rich, plain, fmtKun, tts } from './data.js';
import { nav, $, $$, bar, toast, ST, stTag, screen, loading, emptyState, range, order, deck, quiz, isRight } from './ui.js';

const CAT = { verb: 'Verb', noun: 'Noun', 'noun/other':'Noun / other', loanword:'Loanword', phrase:'Phrase', 'i-adjective': 'い-adjective', 'na-adjective': 'な-adjective', adverb: 'Adverb', expression: 'Expression' };
const SUBN = { vocab: 'Vocabulary', grammar: 'Grammar', reading: 'Reading', listening: 'Listening' };
const pct = (a, b) => b ? Math.round(a / b * 100) : 0;
const uniq = (a, n) => { const o = new Set(); for (const x of shuffle(a)) { if (!o.has(x)) o.add(x); if (o.size >= n) break; } return [...o]; };
const opts4 = (ans, pool) => shuffle([ans, ...uniq(pool.filter(x => x !== ans), 3)]);
const examMode = () => store.pref('examMode');
const lvSeg = () => `<div class="seg" style="width:210px" role="tablist"><button class="" data-lv="N5">N5</button><button class="on">N4</button><button class="lock" disabled aria-label="N3 coming soon">N3</button><button class="lock" disabled aria-label="N2 coming soon">N2</button></div>`;

// ================= HOME =================
export async function home() {
  const [v, g, k, pp] = await Promise.all([load('n4/vocab'), load('n4/grammar'), load('n5/kanji'), load('n4/papers')]);
  const vs = store.count('v:', x => x.seen > 0), ks = store.count('k:', x => x.seen > 0), gs = store.count('g:', x => x.seen > 0);
  const exams = Object.values(store.exams()), done = exams.length, bestPct = exams.length ? Math.max(...exams.map(e => e.best)) / 180 : null;
  const readiness = Math.round(100 * ((bestPct ?? 0) * (bestPct == null ? 0 : .5) + (vs ? Math.min(1, store.count('v:', x => x.st === 'known' || x.box >= 3) / v.words.length) : 0) * (bestPct == null ? .45 : .2) + Math.min(1, gs / g.points.length) * (bestPct == null ? .3 : .15) + Math.min(1, ks / k.kanji.length) * (bestPct == null ? .25 : .15)));
  const hasData = vs + ks + gs + done > 0;
  const d = store.pref('examDate'), days = d ? Math.ceil((new Date(d) - new Date(new Date().toDateString())) / 864e5) : null;
  const today = store.todayCount(), goal = store.pref('goal'), due = store.due(['v:', 'k:', 'g:']).length;
  const tags = Object.entries(store.tags()).filter(([, t]) => t.all >= 3).map(([n, t]) => [n, pct(t.ok, t.all), t.all]).sort((a, b) => a[1] - b[1]).slice(0, 3);
  const tile = (ic, t, s, h, p) => `<div class="card tile press" data-go="${h}" role="link" tabindex="0"><div class="ico">${ic.length > 3 ? I(ic) : ic}</div><div><b>${t}</b><span class="s">${s}</span></div>${bar(p)}</div>`;
  const nm = store.recents()[0];
  screen({ big: 'Welcome back', sub: days != null ? (days > 0 ? `${days} day${days > 1 ? 's' : ''} to your JLPT N4 exam` : days === 0 ? 'Your exam is today. Good luck.' : 'Set your next exam date in Settings') : 'Set your exam date in Settings to see a countdown', right: lvSeg(), body: `<div class="cols"><div>
  <div class="card hero"><div class="row gap"><div class="ring" style="--p:${hasData ? readiness : 0}"><div>${hasData ? readiness + '%' : '–'}</div></div><div class="grow"><div class="xs" style="opacity:.8;font-weight:600;letter-spacing:.05em">EXAM READINESS (ESTIMATE)</div><div style="font-size:19px;font-weight:700;letter-spacing:-.02em;margin:2px 0 8px">${!hasData ? 'Start studying to see your estimate' : readiness >= 70 ? 'Looking strong' : readiness >= 40 ? 'Building momentum' : 'Early days. Keep going.'}</div><div class="xs" style="opacity:.85">${done} of 10 mock exams done${bestPct != null ? ` · best ${Math.round(bestPct * 180)}/180` : ''}</div></div></div></div>
  ${nm ? `<div class="card press" data-go="${nm.href}" role="link" tabindex="0"><div class="row"><div class="ico">${I('play')}</div><div class="grow"><div class="xs mut">Continue where you left off</div><b>${esc(nm.label)}</b></div>${I('right', 'sm')}</div></div>` : ''}
  <h2>Study</h2><div class="grid2">${tile('book', 'Vocabulary', `${v.words.length} words · kana only`, '#/vocab', pct(vs, v.words.length))}${tile('字', 'Kanji', `${k.kanji.length} N5 kanji`, '#/kanji', pct(ks, k.kanji.length))}${tile('grid', 'Grammar', `${g.points.length} patterns`, '#/grammar', pct(gs, g.points.length))}${tile('open', 'Dokkai', 'Reading practice', '#/dokkai', pct(store.count('d:', x => x.seen > 0), 7))}${tile('phones', 'Chokai', 'Listening practice', '#/chokai', pct(store.count('c:', x => x.seen > 0), 10))}${tile('clip', 'Mock exams', `${done} of 10 complete`, '#/exams', done * 10)}</div></div>
  <div><div class="card"><div class="row between"><h3>Today</h3><span class="tag">${Math.min(today, goal)} / ${goal}</span></div><div style="margin:12px 0">${bar(pct(today, goal))}</div><div class="sm mut">${store.streak()} day streak · ${due ? `${due} item${due > 1 ? 's' : ''} due for review` : 'nothing due for review'}</div><div class="row" style="margin-top:12px"><button class="btn pri grow" data-go="#/review">${I('redo', 'sm')}Spaced review</button></div></div>
  <div class="card"><h3>Focus areas</h3>${tags.length ? tags.map(([n, p]) => `<div class="line"><span>${esc(n)}</span><span class="tag ${p < 50 ? 'bad' : p < 70 ? 'warn' : 'ok'}">${p}%</span></div>`).join('') : '<p class="mut sm" style="margin:6px 0 0">Complete some quizzes and your weakest topics will appear here.</p>'}</div></div></div>` });
}

// ================= LEARN HUB =================
export function learn() {
  screen({ big: 'Learn', sub: 'Everything for JLPT N4, organised like the exam.', body: `<div class="card"><button class="btn pri" data-go="#/custom">Custom Mock Exam</button><button class="btn" data-go="#/hard">Revise Hard</button></div><div class="grid2">${[['book', 'Vocabulary', 'Kana only · flashcards · quizzes', '#/vocab'], ['字', 'Kanji', 'N4 and N5 study', '#/kanji'], ['grid', 'Grammar', 'Patterns and drills', '#/grammar'], ['open', 'Dokkai', 'Reading, Mondai 4–6', '#/dokkai'], ['phones', 'Chokai', 'Listening, Mondai 1–4', '#/chokai'], ['clip', 'Mock exams', 'Custom exams + sample paper', '#/exams']].map(([ic, t, s, h]) => `<div class="card tile press" data-go="${h}" role="link" tabindex="0"><div class="ico">${ic.length > 3 ? I(ic) : ic}</div><div><b>${t}</b><span class="s">${s}</span></div></div>`).join('')}</div>` });
}

// ================= VOCABULARY =================
export async function vocab() {
  const D = await load('n4/vocab'), nums = D.lessons.map(l => l.n), nm = Object.fromEntries(D.lessons.map(l => [l.n, l.name]));
  const known = store.count('v:', x => x.st === 'known'), hard = store.keys('v:', x => x.st === 'difficult');
  let fmt = 'kana-meaning', cnt = 20;
  screen({ back: '#/learn', big: 'Vocabulary', sub: `${D.words.length} words across ${D.lessons.length} lessons. Kana only, no kanji.`, body: `<div id="rg"></div>
  <h2>Study mode</h2><div class="grid2"><div class="card tile press" id="m-flash" style="margin:0" role="button" tabindex="0"><div class="ico">${I('layers')}</div><div><b>Flashcards</b><span class="s">Flip and self-rate</span></div></div><div class="card tile press" id="m-quiz" style="margin:0" role="button" tabindex="0"><div class="ico">${I('check')}</div><div><b>Quiz</b><span class="s">Test yourself</span></div></div><div class="card tile press" id="m-list" style="margin:0" role="button" tabindex="0"><div class="ico">${I('list')}</div><div><b>Word list</b><span class="s">Browse and mark</span></div></div><div class="card tile press" id="m-hard" style="margin:0" role="button" tabindex="0"><div class="ico">${I('alert')}</div><div><b>Difficult words</b><span class="s">${hard.length} to revise</span></div></div></div>
  <h2>Quiz options</h2><div class="card"><label class="l">Format</label><div class="seg" id="fmt"><button class="on" data-f="kana-meaning">Kana to meaning</button><button data-f="meaning-kana">Meaning to kana</button><button data-f="type">Type the kana</button></div><label class="l" style="margin-top:14px">Questions</label><div class="seg" id="cnt"><button data-c="10">10</button><button class="on" data-c="20">20</button><button data-c="40">40</button><button data-c="0">All</button></div><div class="note" style="text-align:left">${examMode() ? 'Exam mode is on: answers are shown only at the end.' : 'Instant feedback is on. Switch to exam mode in Settings.'}</div></div>` });
  const R = range($('#rg'), { key: 'vocab', nums, label: n => `Lesson ${n}`, noun: 'words', count: sel => D.words.filter(w => sel.includes(w.lesson)).length });
  $$('#fmt button').forEach(b => b.onclick = () => { fmt = b.dataset.f; $$('#fmt button').forEach(x => x.classList.toggle('on', x === b)); });
  $$('#cnt button').forEach(b => b.onclick = () => { cnt = +b.dataset.c; $$('#cnt button').forEach(x => x.classList.toggle('on', x === b)); });
  const pick = (filter) => { const r = R.get(); let a = order(D.words, r.nums, 'lesson', r.shuffle); if (filter) a = a.filter(filter); return a; };
  $('#m-flash').onclick = () => { const items = pick(); store.recent('Vocabulary flashcards', '#/vocab'); deck({ title: 'Vocabulary', sub: 'Kana → meaning', back: '#/vocab', items, key: w => 'v:' + w.id, dirA: 'Kana to meaning', dirB: 'Meaning to kana',
    front: w => `<span class="xs mut">TAP TO REVEAL</span><div class="big">${esc(w.kana)}</div><span class="xs mut">Lesson ${w.lesson} · ${esc(nm[w.lesson])}</span>`,
    reveal: w => `<span class="xs mut">MEANING</span><div class="big" style="font-size:30px">${esc(w.en)}</div><div class="tag">${CAT[w.cat]}</div><div class="sm mut">Reading: ${esc(w.kana)}</div>` }); };
  $('#m-hard').onclick = () => { const items = D.words.filter(w => store.item('v:' + w.id).st === 'difficult'); deck({ title: 'Difficult words', back: '#/vocab', items: shuffle(items), key: w => 'v:' + w.id, empty: 'No difficult words yet. Mark cards as Hard while studying, or miss them in a quiz.', drop: s => s !== 'difficult',
    front: w => `<div class="big">${esc(w.kana)}</div>`, reveal: w => `<div class="big" style="font-size:30px">${esc(w.en)}</div><div class="tag">${CAT[w.cat]}</div>` }); };
  $('#m-list').onclick = () => { const items = pick(); store.recent('Vocabulary list', '#/vocab'); vocabList(items, nm); };
  $('#m-quiz').onclick = () => { const items = pick(); const n = cnt || items.length; const sel = items.slice(0, n);
    if (sel.length < 4) return toast('Select at least 4 words for a quiz', 'bad');
    const all = D.words; const qs = sel.map(w => { const same = all.filter(x => x.cat === w.cat && x.en !== w.en); const tag = `Vocab: ${nm[w.lesson]}`;
      if (fmt === 'kana-meaning') return { type: 'mc', key: 'v:' + w.id, tag, prompt: `<div class="xs mut" style="font-weight:600;letter-spacing:.06em">WHAT DOES THIS MEAN?</div><div style="font-size:42px;font-weight:700;margin-top:8px">${esc(w.kana)}</div>`, options: opts4(w.en, same.map(x => x.en)), answer: w.en, explain: `<b>${esc(w.kana)}</b> means <b>${esc(w.en)}</b> (${CAT[w.cat]}, Lesson ${w.lesson}).` };
      if (fmt === 'meaning-kana') return { type: 'mc', key: 'v:' + w.id, tag, prompt: `<div class="xs mut" style="font-weight:600;letter-spacing:.06em">WHICH WORD MEANS</div><div style="font-size:26px;font-weight:700;margin-top:8px">${esc(w.en)}</div>`, options: opts4(w.kana, same.map(x => x.kana)), answer: w.kana, explain: `${esc(w.en)} is <b>${esc(w.kana)}</b> (${CAT[w.cat]}, Lesson ${w.lesson}).` };
      return { type: 'type', key: 'v:' + w.id, tag, prompt: `<div class="xs mut" style="font-weight:600;letter-spacing:.06em">TYPE THIS WORD IN KANA</div><div style="font-size:26px;font-weight:700;margin-top:8px">${esc(w.en)}</div>`, answer: w.kana, explain: `${esc(w.en)} = <b>${esc(w.kana)}</b> (${CAT[w.cat]}, Lesson ${w.lesson}).` }; });
    store.recent('Vocabulary quiz', '#/vocab'); quiz({ title: 'Vocabulary quiz', back: '#/vocab', questions: qs, examMode: examMode(), mode: 'Vocabulary quiz' }); };
}
function vocabList(items, nm) {
  let q = '', shown = 60;
  const draw = () => { const t = q.toLowerCase(), rows = items.filter(w => !t || w.kana.includes(q) || w.en.toLowerCase().includes(t));
    screen({ back: '#/vocab', big: 'Word list', sub: `${rows.length} of ${items.length} words`, body: `<div class="row"><input id="sq" type="text" placeholder="Search kana or English" value="${esc(q)}" aria-label="Search words" autocomplete="off"></div><div class="card vlist" style="margin-top:12px">${rows.slice(0, shown).map(w => `<div class="line"><div class="grow"><div class="vjp">${esc(w.kana)}</div><div class="sm mut">${esc(w.en)} · ${CAT[w.cat]} · L${w.lesson}</div></div>${stTag(store.item('v:' + w.id).st)}<button class="btn sm" data-t="${w.id}" aria-label="Cycle status for ${esc(w.kana)}">${I('flag', 'sm')}</button></div>`).join('') || '<p class="mut">No words match.</p>'}</div>${rows.length > shown ? `<button class="btn blk" id="more">Show more (${rows.length - shown})</button>` : ''}` });
    const s = $('#sq'); s.oninput = e => { q = e.target.value; shown = 60; draw(); const n = $('#sq'); n.focus(); n.setSelectionRange(1e3, 1e3); };
    if ($('#more')) $('#more').onclick = () => { shown += 60; draw(); };
    $$('[data-t]').forEach(b => b.onclick = () => { const k = 'v:' + b.dataset.t, cur = store.item(k).st, nx = { null: 'learning', learning: 'known', known: 'difficult', difficult: null }[cur]; if (nx) store.setStatus(k, nx); else { const it = store.item(k); it.st = null; store.touch(k); } const y = scrollY; draw(); scrollTo(0, y); }); };
  draw();
}

// ================= KANJI =================
const KIND = { on: 'onyomi (sound reading, mostly in compounds)', kun: 'kunyomi (native reading)', special: 'an irregular / fixed reading' };
function guide(k) {
  const by = t => (k.ex || []).filter(e => e[3] === t), fmt = a => a.slice(0, 6).map(e => `<span class="exw"><b>${esc(e[0])}</b> <i>${esc(e[1])}</i> <span class="mut xs">${esc(e[2])}</span></span>`).join('');
  return [k.on.length ? `<div class="rd on"><h3>Onyomi <span class="kata">${k.on.map(esc).join('・')}</span></h3><p>Sound-based reading. In these lessons it mostly appears inside <b>kanji compounds</b>.</p>${by('on').length ? fmt(by('on')) : '<p>No example for this reading in the source.</p>'}</div>` : '',
    k.kun.length ? `<div class="rd kun"><h3>Kunyomi <span class="hira">${k.kun.map(fmtKun).map(esc).join('・')}</span></h3><p>Native reading. Seen when the kanji is a <b>word by itself</b> or has <b>hiragana endings</b> (the part in brackets).</p>${by('kun').length ? fmt(by('kun')) : '<p>No example for this reading in the source.</p>'}</div>` : '',
    by('special').length ? `<div class="rd sp"><h3>Irregular readings</h3><p>Learn these as whole words.</p>${fmt(by('special'))}</div>` : ''].join('');
}
export async function kanji() {
  const level = store.pref('kanjiLevel') || 'n5'; const D = await load(level+'/kanji'), all = D.kanji; let sel = new Set(), fmtK = 'flash', cnt = 20;
  screen({ back: '#/learn', big: 'Kanji', sub: 'Choose by level, lesson range, or hand-pick.', body: `<div class="card"><label class="l">Level</label><div class="chips"><button class="chip" id="level5">N5</button><button class="chip" id="level4">N4</button></div></div><div id="rg"></div>
  <div class="row between"><h2 style="margin-bottom:10px">Or pick individual kanji</h2><span class="sm mut" id="kc">none selected</span></div><div class="kg" id="kg">${all.map(k => `<button data-k="${k.id}" aria-pressed="false" aria-label="${esc(k.k)} ${esc(k.en)}">${esc(k.k)}</button>`).join('')}</div>
  <div class="chips" style="margin:12px 0"><button class="chip" id="sa">Select all</button><button class="chip" id="sc">Clear</button><button class="chip" id="sd">Difficult only</button></div>
  <h2>Study mode</h2><div class="grid2"><button class="btn pri" data-m="flash">${I('layers', 'sm')}Flashcards</button><button class="btn pri" data-m="kread">${I('check', 'sm')}Reading quiz</button><button class="btn" data-m="kmean">Meaning quiz</button><button class="btn" data-m="konkun">On vs Kun quiz</button></div>
  <div class="card" style="margin-top:12px"><label class="l">Questions per quiz</label><div class="seg" id="cnt"><button data-c="10">10</button><button class="on" data-c="20">20</button><button data-c="40">40</button><button data-c="0">All</button></div></div><div id="det"></div>` });
  $('#level5').onclick=()=>{store.setPref('kanjiLevel','n5');kanji();}; $('#level4').onclick=()=>{store.setPref('kanjiLevel','n4');kanji();}; const R = range($('#rg'), { key: 'kanji-'+level, unit: level==='n4'?'Kanji':'Lesson', nums: level==='n4'?all.map(k=>k.number):D.lessons, noun: 'kanji', count: s => all.filter(k => s.includes(level==='n4'?k.number:k.lessonNo)).length });
  const upd = () => { $('#kc').textContent = sel.size ? `${sel.size} selected` : 'none selected'; $$('#kg button').forEach(b => { const on = sel.has(b.dataset.k); b.classList.toggle('s', on); b.setAttribute('aria-pressed', on); }); };
  $('#kg').onclick = e => { const b = e.target.closest('[data-k]'); if (!b) return; sel.has(b.dataset.k) ? sel.delete(b.dataset.k) : sel.add(b.dataset.k); upd(); showDet(b.dataset.k); };
  $('#sa').onclick = () => { all.forEach(k => sel.add(k.id)); upd(); }; $('#sc').onclick = () => { sel.clear(); upd(); };
  $('#sd').onclick = () => { sel = new Set(all.filter(k => store.item('k:' + k.id).st === 'difficult').map(k => k.id)); upd(); if (!sel.size) toast('No difficult kanji yet'); };
  $$('#cnt button').forEach(b => b.onclick = () => { cnt = +b.dataset.c; $$('#cnt button').forEach(x => x.classList.toggle('on', x === b)); });
  const showDet = id => { const k = all.find(x => x.id === id); store.touch('k:' + id); $('#det').innerHTML = `<div class="card"><div class="row gap"><div style="font-size:72px;line-height:1.1">${esc(k.k)}</div><div class="grow"><h3>${esc(k.en)} ${stTag(store.item('k:' + id).st)}</h3><div class="sm" style="margin-top:6px"><span class="xs mut">ONYOMI</span> <span class="kata">${esc(k.on.join('・') || '—')}</span></div><div class="sm"><span class="xs mut">KUNYOMI</span> <span class="hira">${esc(k.kun.map(fmtKun).join('・') || '—')}</span></div></div></div><div class="tip">${esc(k.note)}</div><h3 style="margin-top:12px">When is each reading used?</h3>${guide(k)}<div class="xs mut">These patterns are tendencies from your lessons, not universal rules.</div></div>`; $('#det').scrollIntoView({ behavior: 'smooth', block: 'nearest' }); };
  const pick = () => { if (sel.size) return all.filter(k => sel.has(k.id)); const r = R.get(); return order(all, r.nums, level==='n4'?'number':'lessonNo', false); };
  $$('[data-m]').forEach(b => b.onclick = () => { let items = pick(); if (R.get().shuffle || sel.size) items = shuffle(items); const m = b.dataset.m;
    if (!items.length) return toast('Nothing selected', 'bad');
    if (m === 'flash') { store.recent('Kanji flashcards', '#/kanji'); return deck({ title: 'Kanji', back: '#/kanji', items, key: k => 'k:' + k.id, dirA: 'Kanji to meaning', dirB: 'Meaning to kanji',
      front: k => `<div class="kb">${esc(k.k)}</div><span class="xs mut">Lesson ${k.lessonNo}</span>`,
      reveal: k => `<div style="font-size:24px;font-weight:700">${esc(k.en)}</div><div class="row" style="gap:26px"><div><div class="xs mut">ONYOMI</div><b class="kata" style="font-size:19px">${esc(k.on.join('・') || '—')}</b></div><div><div class="xs mut">KUNYOMI</div><b class="hira" style="font-size:19px">${esc(k.kun.map(fmtKun).join('・') || '—')}</b></div></div><div>${(k.ex || []).slice(0, 3).map(e => `<span class="exw"><b>${esc(e[0])}</b> <i>${esc(e[1])}</i></span>`).join('')}</div>` }); }
    const n = cnt || items.length; const qs = kanjiQs(m, items.slice(0, n), all); if (qs.length < 1) return toast('Not enough material for that quiz', 'bad');
    store.recent('Kanji quiz', '#/kanji'); quiz({ title: { kread: 'Kanji reading quiz', kmean: 'Kanji meaning quiz', konkun: 'On vs Kun quiz' }[m], back: '#/kanji', questions: qs, examMode: examMode(), mode: 'Kanji ' + m }); });
}
function kanjiQs(m, items, all) {
  const qs = [], reads = all.flatMap(k => (k.ex || []).map(e => e[1]));
  for (const k of items) {
    if (m === 'kmean') qs.push({ type: 'mc', key: 'k:' + k.id, tag: `Kanji: lesson ${k.lessonNo}`, prompt: `<div class="xs mut" style="font-weight:600">WHAT DOES THIS KANJI MEAN?</div><div style="font-size:76px;line-height:1.2">${esc(k.k)}</div>`, options: opts4(k.en, all.map(x => x.en)), answer: k.en, explain: `<b>${esc(k.k)}</b> = ${esc(k.en)}. ${esc(k.note)}` });
    else if (m === 'kread') { const exs = (k.ex || []).filter(e => !e[0].includes('〜')); if (!exs.length) {const valid=[...k.kun,...k.on];if(!valid.length)continue;const answer=valid[0];qs.push({type:'mc',key:'k:'+k.id,tag:'Kanji: source reading',prompt:'<div class="big">'+esc(k.k)+'</div><p>Choose a reading supplied in '+esc(k.source)+'</p>',answer,options:shuffle([answer,...uniq(all.flatMap(x=>[...x.kun,...x.on]).filter(r=>!valid.includes(r)),3)]),explain:esc('On: '+k.on.join(' / ')+' · Kun: '+k.kun.join(' / ')+' · '+k.en)});continue;} const e = exs[Math.floor(Math.random() * exs.length)];
      qs.push({ type: 'mc', key: 'k:' + k.id, tag: `Kanji: lesson ${k.lessonNo}`, prompt: `<div class="xs mut" style="font-weight:600">HOW IS THIS WORD READ? (${esc(e[2])})</div><div style="font-size:48px;line-height:1.3">${esc(e[0])}</div>`, options: opts4(e[1], reads.filter(r => Math.abs(r.length - e[1].length) <= 2)), answer: e[1], explain: `<b>${esc(e[0])}</b> is read <b>${esc(e[1])}</b> (${esc(e[2])}), ${KIND[e[3]]}.<br><span class="xs mut">${esc(k.note)}</span>` }); }
    else { const ons = k.on.map(r => [r, 'on']), kuns = k.kun.map(r => [r, 'kun']), all2 = [...ons, ...kuns]; if (!all2.length) continue; const [r, t] = all2[Math.floor(Math.random() * all2.length)]; const ex = (k.ex || []).filter(e => e[3] === t).slice(0, 3).map(e => `${e[0]} (${e[1]})`).join(', ');
      qs.push({ type: 'mc', key: 'k:' + k.id, tag: 'Kanji: onyomi vs kunyomi', fixed: true, prompt: `<div class="xs mut" style="font-weight:600">IS THIS A READING OF ${esc(k.k)} ONYOMI OR KUNYOMI?</div><div style="font-size:40px;font-weight:700;margin-top:6px">${esc(t === 'on' ? r : fmtKun(r))}</div>`, options: ['Onyomi (katakana)', 'Kunyomi (hiragana)'], answer: t === 'on' ? 'Onyomi (katakana)' : 'Kunyomi (hiragana)', explain: `<b>${esc(r)}</b> is a ${t === 'on' ? 'onyomi' : 'kunyomi'} reading of ${esc(k.k)} (${esc(k.en)}).${ex ? ' Used in: ' + esc(ex) + '.' : ''}` }); }
  }
  return qs;
}

// ================= GRAMMAR =================
export async function grammar() {
  const D = await load('n4/grammar'), nums = [...new Set(D.points.map(p => p.lesson))].sort((a, b) => a - b);
  screen({ back: '#/learn', big: 'Grammar', sub: `${D.points.length} N4 patterns with exam-style drills`, body: `<div id="rg"></div><div class="grid2"><button class="btn pri" id="gs">${I('book', 'sm')}Study notes</button><button class="btn pri" id="g1">${I('check', 'sm')}Mondai 1 drill</button><button class="btn" id="g2">Mondai 2 · Sentence building</button><button class="btn" id="g3">Mixed drill</button></div><div class="note">${examMode() ? 'Exam mode on: answers shown at the end.' : 'Instant feedback on. Change in Settings.'}</div><div id="gl"></div>` });
  const R = range($('#rg'), { key: 'grammar', unit: 'Lesson', nums, noun: 'patterns', count: s => D.points.filter(p => s.includes(p.lesson)).length });
  const pick = () => { const r = R.get(); return order(D.points, r.nums, 'lesson', r.shuffle); };
  const mc1 = p => ({ type: 'mc', key: 'g:' + p.id, tag: `Grammar: ${p.p}`, prompt: `<div class="xs mut" style="font-weight:600">CHOOSE THE BEST ANSWER</div><div style="font-size:21px;line-height:1.9;margin-top:8px">${esc(p.q.s)}</div>`, options: shuffle(p.q.o), answer: p.q.o[p.q.a], explain: `${esc(p.q.e)}<br><span class="xs mut"><b>${esc(p.p)}</b> · ${esc(p.m)}</span>` });
  const ord = o => ({ type: 'mc', key: 'g:o' + o.id, tag: 'Grammar: sentence building', prompt: `<div class="xs mut" style="font-weight:600">PUT THE BLOCKS IN ORDER. WHICH GOES IN THE ★ SPACE?</div><div style="font-size:21px;line-height:1.9;margin:8px 0">${esc(o.s)}</div><div class="sm mut">Blocks: ${shuffle(o.parts).map(esc).join(' / ')}</div>`, options: shuffle(o.parts), answer: o.parts[2], explain: `${esc(o.e)}` });
  const gf=document.createElement('button'); gf.className='btn';gf.textContent='Grammar flashcards';$('#gs').before(gf);gf.onclick=()=>deck({title:'Grammar',back:'#/grammar',items:pick(),key:x=>'g:'+x.id,front:x=>esc(x.p),reveal:x=>esc(x.m+' · '+x.form)});
  $('#gs').onclick = () => { const items = pick(); store.recent('Grammar notes', '#/grammar'); $('#gl').innerHTML = items.length ? `<h2>${items.length} patterns</h2>${items.map(p => `<details class="card"><summary><div><b style="font-size:17px">${esc(p.p)}</b><div class="sm mut">${esc(p.m)}</div></div><span class="tag">L${p.lesson}</span></summary><div class="sm" style="margin-top:12px"><b>Form:</b> ${esc(p.form)}</div><div class="tip">${esc(p.note)}</div>${p.ex.map(e => `<div class="ex"><div class="jp">${esc(e[0])}</div><div class="mut sm">${esc(e[1])}</div></div>`).join('')}</details>`).join('')}` : emptyState('No patterns', 'Widen the lesson range.'); $('#gl').scrollIntoView({ behavior: 'smooth' }); };
  const run = (qs, t) => { if (!qs.length) return toast('Nothing to practise in that range', 'bad'); store.recent(t, '#/grammar'); quiz({ title: t, back: '#/grammar', questions: qs, examMode: examMode(), mode: t }); };
  $('#g1').onclick = () => run(pick().slice(0, 15).map(mc1), 'Grammar Mondai 1');
  $('#g2').onclick = () => run(shuffle(D.ordering).map(ord), 'Grammar Mondai 2');
  $('#g3').onclick = () => run(shuffle([...pick().slice(0, 12).map(mc1), ...D.ordering.map(ord)]), 'Grammar mixed drill');
}

// ================= DOKKAI =================
