    const left = Math.max(0, Math.round((E.deadline - Date.now()) / 1000)), mm = String(Math.floor(left / 60)).padStart(2, '0'), ss = String(left % 60).padStart(2, '0');
    const ans = Object.keys(E.A).filter(k => k.startsWith(E.si + '-')).length;
